sealed trait State
sealed trait Closed extends State
sealed trait Open   extends State

class Door[S <: State] private () {
  def open(using ev: S =:= Closed): Door[Open]   = new Door[Open]
  def close(using ev: S =:= Open):  Door[Closed] = new Door[Closed]
}
// new Door[Closed]().open.close.open; close() on a Closed door has no evidence
